import{_ as d,C as A,o as s,c as g,j as o,a as r,b as i,w as l,E as n,a3 as e,a2 as E}from"./chunks/framework.l6sz0Vgx.js";const c=JSON.parse('{"title":"基础笔记","description":"一次请求之旅 — 网络 + 操作系统","frontmatter":{"title":"基础笔记","description":"一次请求之旅 — 网络 + 操作系统"},"headers":[],"relativePath":"posts/basics.md","filePath":"posts/basics.md","lastUpdated":1791724316000}'),B={name:"posts/basics.md"};function C(T,t,u,S,P,h){const a=A("Mermaid");return s(),g("div",null,[t[3]||(t[3]=o("h1",{id:"基础笔记",tabindex:"-1"},[r("基础笔记 "),o("a",{class:"header-anchor",href:"#基础笔记","aria-label":'Permalink to "基础笔记"'},"​")],-1)),t[4]||(t[4]=o("p",null,[o("strong",null,"摘要："),r(" 一次请求之旅：浏览器发出 URL，DNS 指路，TCP/TLS 建连，网关转发，进程线程干活，虚拟内存供货——网络与操作系统在此相遇。与《Go笔记》（GMP/锁实现）、《存储笔记》（DB/缓存）分工：本篇讲 requests 之下的路和地基。")],-1)),t[5]||(t[5]=o("p",null,[o("strong",null,"怎么读："),r(' §1–§2 跟请求走（DNS → TCP → HTTP），§3–§4 看地基（进程线程 → 内存），§5 看性能（缓存与延迟），§6 看安全。标"常问"的是高频口述点。')],-1)),(s(),i(e,null,{default:l(()=>[n(a,{id:"mermaid-9",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20B%5B%22%E6%B5%8F%E8%A7%88%E5%99%A8%3Cbr%2F%3E%E8%A7%A3%E6%9E%90%20URL%22%5D%20--%3E%20D%5B%22DNS%3Cbr%2F%3E%E9%80%92%E5%BD%92%E5%8A%A0%E8%BF%AD%E4%BB%A3%22%5D%0A%20%20%20%20D%20--%3E%20T%5B%22TCP%20%E4%B8%89%E6%AC%A1%E6%8F%A1%E6%89%8B%3Cbr%2F%3E%E5%8A%A0%20TLS%22%5D%0A%20%20%20%20T%20--%3E%20G%5B%22%E7%BD%91%E5%85%B3%20LB%3Cbr%2F%3E%E8%BD%AC%E5%8F%91%22%5D%0A%20%20%20%20G%20--%3E%20P%5B%22%E8%BF%9B%E7%A8%8B%E7%BA%BF%E7%A8%8B%3Cbr%2F%3E%E5%A4%84%E7%90%86%E8%AF%B7%E6%B1%82%22%5D%0A%20%20%20%20P%20--%3E%20M%5B%22%E8%99%9A%E6%8B%9F%E5%86%85%E5%AD%98%3Cbr%2F%3E%E7%BC%BA%E9%A1%B5%E8%B0%83%E9%A1%B5%22%5D%0A%20%20%20%20M%20--%3E%20R%5B%22%E5%93%8D%E5%BA%94%E6%B8%B2%E6%9F%93%22%5D%0A"})]),fallback:l(()=>[...t[0]||(t[0]=[r(" Loading... ",-1)])]),_:1})),t[6]||(t[6]=E('<h2 id="_1-dns-与建连" tabindex="-1">1. DNS 与建连 <a class="header-anchor" href="#_1-dns-与建连" aria-label="Permalink to &quot;1. DNS 与建连&quot;">​</a></h2><p><strong>一句话：DNS 把名字变地址（递归对用户、迭代对根），TCP 把地址变可靠连接（握手对序号、挥手保完整）。</strong></p><ul><li><strong>DNS：</strong> 递归（解析器查出最终答案再返回）vs 迭代（每级给下一跳，查询方自己走）；通常 UDP/53，大报文/区传送/DoH 用 TCP；记录 A/AAAA/CNAME/MX/NS/TXT；缓存 + 负载均衡是常规操作。</li><li><strong>三次握手/四次挥手：</strong> 握手同步序列号建连；挥手保证数据完整关闭。滑动窗口做流量控制（ACK 推进），拥塞控制（慢启动/避免/快重传/快恢复）保吞吐。</li><li><strong>TLS 握手：</strong> ClientHello（版本/随机数/套件）→ ServerHello（证书/随机数）→ 协商会话密钥 → Finished 后对称加密通信。防劫持：证书链验到根 + 域名匹配 + HSTS。</li><li><strong>HTTP 版本：</strong> 1.1 持久连接 → 2 多路复用 + 头压缩 → 3 QUIC。状态码分段记（2xx/3xx/4xx/5xx）。</li></ul><h2 id="_2-传输细节" tabindex="-1">2. 传输细节 <a class="header-anchor" href="#_2-传输细节" aria-label="Permalink to &quot;2. 传输细节&quot;">​</a></h2><p><strong>一句话：TCP 为可靠付费（20 字节头 + 状态机），UDP 为轻量免单（8 字节头）——TIME_WAIT 和 MTU 是最常见的两个坑。</strong></p><ul><li><strong>TCP vs UDP（常问）：</strong> TCP 面向连接、可靠有序字节流、拥塞控制、点对点；UDP 无连接尽力而为、报文、开销小、可一对多。</li><li><strong>TIME_WAIT vs CLOSE_WAIT（常问）：</strong> 前者主动关闭方等 2MSL（保 ACK 到达 + 旧报文消失，短连接多则多）；后者收到 FIN 但本端没 close（代码漏关连接）。</li><li><strong>MTU：</strong> 链路最大传输单元；超限分片（丢包放大 + 重组成本）或 PMTUD 探测。</li><li><strong>socket 关闭读到什么：</strong> 对端正常关读 EOF；异常断开可 <code>Connection reset</code>。本机 <code>127.0.0.1</code> 照样走协议栈（loopback 不开网卡）；UNIX 域 socket 不走 IP/TCP 更省。</li><li><strong>SYN Flood：</strong> 半连接耗 backlog；防：SYN cookie、调大队列、限流黑白名单、WAF/清洗、弹性扩容。</li></ul><h3 id="tcp-建连时序与拥塞-常问" tabindex="-1">TCP 建连时序与拥塞（常问） <a class="header-anchor" href="#tcp-建连时序与拥塞-常问" aria-label="Permalink to &quot;TCP 建连时序与拥塞（常问）&quot;">​</a></h3>',7)),(s(),i(e,null,{default:l(()=>[n(a,{id:"mermaid-74",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20C%20as%20%E5%AE%A2%E6%88%B7%E7%AB%AF%0A%20%20%20%20participant%20S%20as%20%E6%9C%8D%E5%8A%A1%E7%AB%AF%0A%20%20%20%20C-%3E%3ES%3A%20SYN%20seq%3Dx%0A%20%20%20%20S-%3E%3EC%3A%20SYN%2BACK%20seq%3Dy%20ack%3Dx%2B1%0A%20%20%20%20C-%3E%3ES%3A%20ACK%20ack%3Dy%2B1%EF%BC%88%E5%BB%BA%E8%BF%9E%EF%BC%89%0A%20%20%20%20C-%3E%3ES%3A%20%E6%95%B0%E6%8D%AE%EF%BC%88%E5%BA%8F%E5%8F%B7%2B%E7%A1%AE%E8%AE%A4%2B%E9%87%8D%E4%BC%A0%EF%BC%89%0A%20%20%20%20C-%3E%3ES%3A%20FIN%EF%BC%88%E5%85%B3%E9%97%AD%EF%BC%89%0A%20%20%20%20S-%3E%3EC%3A%20ACK%0A%20%20%20%20S-%3E%3EC%3A%20FIN%0A%20%20%20%20C-%3E%3ES%3A%20ACK%EF%BC%88TIME_WAIT%202MSL%EF%BC%89%0A"})]),fallback:l(()=>[...t[1]||(t[1]=[r(" Loading... ",-1)])]),_:1})),t[7]||(t[7]=E('<ul><li><strong>拥塞控制四阶段：</strong> 慢启动（指数涨）→ 拥塞避免（线性涨）→ 快重传（3 个重复 ACK 即重发）→ 快恢复（阈值减半续发）。</li><li><strong>粘包/拆包：</strong> TCP 是字节流无边界；解：定长包、分隔符、头体结构（先读定长头得长度再读体）。</li><li><strong>UDP 适用：</strong> DNS、QUIC（HTTP/3）、实时音视频（丢包可容忍、延迟敏感）、广播（DHCP）。</li></ul><h2 id="_3-进程、线程与同步" tabindex="-1">3. 进程、线程与同步 <a class="header-anchor" href="#_3-进程、线程与同步" aria-label="Permalink to &quot;3. 进程、线程与同步&quot;">​</a></h2><p><strong>一句话：进程是资源单位（隔离），线程是调度单位（共享）——切换成本差一个地址空间，通信方式差一套 IPC。</strong></p><ul><li><strong>区别（常问）：</strong> 地址空间（进程隔离/线程共享）→ 切换成本（线程低，页表不用换）→ 通信（IPC vs 共享内存 + 同步）→ 选型（隔离稳定多进程，共享高并发多线程）。</li><li><strong>PCB：</strong> 寄存器上下文、页表/内存信息、打开文件、优先级——上下文切换保存恢复的就是它。触发：时间片、阻塞唤醒、中断/系统调用、优先级变化；贵在寄存器 + 地址空间/TLB 切换。</li><li><strong>IPC：</strong> 管道/命名管道、信号、消息队列、共享内存（配信号量，效率最高）、socket、文件锁。线程间：互斥/读写/自旋/条件变量/信号量/屏障/CAS。</li><li><strong>死锁（常问）：</strong> 互斥、占有等待、不可抢占、循环等待四条件全齐才死；解：统一加锁顺序、短持锁、超时、少嵌套；检测看资源分配图找环。</li><li><strong>池化：</strong> 复用昂贵资源（连接/对象/线程），减创建销毁与系统调用，平滑突发、有界限并发。</li></ul><h3 id="进程通信对照-常问" tabindex="-1">进程通信对照（常问） <a class="header-anchor" href="#进程通信对照-常问" aria-label="Permalink to &quot;进程通信对照（常问）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方式</th><th>亲缘要求</th><th>方向</th><th>要点</th></tr></thead><tbody><tr><td>匿名管道</td><td>父子</td><td>单向</td><td>简单，容量小（常 64KB）</td></tr><tr><td>命名管道</td><td>无</td><td>单向</td><td>文件路径 rendezvous</td></tr><tr><td>信号</td><td>无</td><td>单向通知</td><td>只传事件不传数据（INT/TERM/KILL/HUP）</td></tr><tr><td>消息队列</td><td>无</td><td>双向</td><td>内核持久，按类型取</td></tr><tr><td>共享内存</td><td>无</td><td>双向</td><td>最快（零拷贝），同步自理</td></tr><tr><td>socket</td><td>无</td><td>双向</td><td>本机/跨机统一，UDS 更省</td></tr><tr><td>文件锁</td><td>无</td><td>互斥</td><td>跨进程互斥与 rendezvous</td></tr></tbody></table><ul><li><strong>常用信号：</strong> INT（Ctrl+C，可捕）/ TERM（优雅退出，默认）/ KILL（强制，不可捕）/ HUP（断开，常作重载配置）。</li><li><strong>共享内存难点：</strong> 进程间同步（共享互斥量/futex/无锁队列）、崩溃恢复（谁清理）、对齐与版本兼容。</li><li><strong>线程同步方式：</strong> 互斥量（mutex）、自旋锁（短临界）、读写锁（读多）、条件变量（等待+唤醒）、信号量（计数限流）、屏障（barrier 会合）、原子操作（CAS）。</li></ul><h2 id="_4-虚拟内存" tabindex="-1">4. 虚拟内存 <a class="header-anchor" href="#_4-虚拟内存" aria-label="Permalink to &quot;4. 虚拟内存&quot;">​</a></h2><p><strong>一句话：进程活在虚拟地址里，MMU + 页表 + TLB 负责翻译，缺页异常负责按需进货。</strong></p>',9)),(s(),i(e,null,{default:l(()=>[n(a,{id:"mermaid-269",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20VA%5B%22%E8%BF%9B%E7%A8%8B%E8%A7%86%E8%A7%92%3Cbr%2F%3E%E8%99%9A%E6%8B%9F%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20PT%5B%22%E9%A1%B5%E8%A1%A8%E5%8A%A0%20TLB%3Cbr%2F%3EMMU%20%E7%BF%BB%E8%AF%91%22%5D%0A%20%20%20%20PT%20--%3E%20PA%5B%22%E7%89%A9%E7%90%86%E5%86%85%E5%AD%98%22%5D%0A%20%20%20%20PT%20--%20%22%E4%B8%8D%E5%9C%A8%E5%86%85%E5%AD%98%22%20--%3E%20PF%5B%22%E7%BC%BA%E9%A1%B5%E5%BC%82%E5%B8%B8%3Cbr%2F%3E%E8%B0%83%E9%A1%B5%E6%9B%B4%E6%96%B0%E8%A1%A8%22%5D%0A%20%20%20%20PF%20--%3E%20PA%0A"})]),fallback:l(()=>[...t[2]||(t[2]=[r(" Loading... ",-1)])]),_:1})),t[8]||(t[8]=E('<ul><li><strong>机制：</strong> demand paging（缺页进货）、COW（写时复制）、权限位（R/W/X）、mmap、swap。价值：隔离安全、按需加载、共享只读页。</li><li><strong>页 vs 段（常问）：</strong> 页固定大小、用户不可见、无外部碎片（有内部）；段按逻辑模块可变长、用户可见、有外部碎片；段页式兼得。</li><li><strong>缺页过程：</strong> 访问不在内存 → 异常 → 查权限 → 磁盘/交换区调页 → 更新页表 TLB → 重执行指令。</li><li><strong>置换算法：</strong> LRU/LFU（留近期高频，工程常用近似）、FIFO（有 Belady 异常）、Clock（访问位近似 LRU）。</li><li><strong>分配器：</strong> 伙伴系统 + slab；优化看工作集（热点常驻、预读）与取舍（内存换 swap、吞吐换延迟）。</li><li><strong>容器 vs 虚拟机：</strong> 容器共享宿主内核（轻），虚拟机虚拟硬件 + 完整 OS（隔离强）。用户态/内核态以系统调用（trap）为界。</li></ul><h3 id="文件系统、调度与-io-模型" tabindex="-1">文件系统、调度与 IO 模型 <a class="header-anchor" href="#文件系统、调度与-io-模型" aria-label="Permalink to &quot;文件系统、调度与 IO 模型&quot;">​</a></h3><ul><li><strong>文件系统：</strong> inode 存元数据（目录是&quot;名→inode&quot;映射）；硬链接同 inode（删原文不影响），软链接是路径（断链即坏）；IO 模型：阻塞/非阻塞、同步/异步、多路复用。</li><li><strong>Linux 调度与中断：</strong> CFS 完全公平调度（vruntime 小的先跑）；中断分顶半部（硬中断速记）+ 底半部（软中断/tasklet/工作队列慢慢做）。</li><li><strong>epoll LT vs ET：</strong> LT 有数据就持续通知（好写）；ET 状态变化才通知（高吞吐，须循环读写到 <code>EAGAIN</code>）。Java NIO 的 Selector 即 Reactor 封装，见《Java/Python笔记》§3。</li></ul><h2 id="_5-性能-缓存、局部性与延迟" tabindex="-1">5. 性能：缓存、局部性与延迟 <a class="header-anchor" href="#_5-性能-缓存、局部性与延迟" aria-label="Permalink to &quot;5. 性能：缓存、局部性与延迟&quot;">​</a></h2><p><strong>一句话：性能优化就是减少&quot;慢层&quot;访问——局部性保命中、对齐保 MESI、延迟表定量级。</strong></p><ul><li><strong>局部性：</strong> 时间（刚用过还会用）+ 空间（相邻会一起用）；优化：连续内存、按行访问、分块、减分支、减指针追逐。</li><li><strong>MESI 与伪共享（常问）：</strong> 多核靠缓存一致性协议保可见；不同变量落同 cache line 被多核写 → 反复失效（伪共享）。解：64B 对齐填充、按线程分片、消灭共享写热点。Go 端见《Go笔记》§2。</li><li><strong>AoS vs SoA：</strong> 对象数组易写，字段数组易批量（SIMD/缓存友好），看访问模式选。</li><li><strong>延迟量级（常问，数量级即可）：</strong> L1 ~0.5ns → 互斥锁 ~25ns → 内存顺序读 ~100ns → SSD 随机读 ~150us → 同机房 RTT ~0.5ms → 磁盘寻道 ~10ms → 跨国 ~150ms+。估算瓶颈先查表：差三个量级就不用压测了。</li><li><strong>零拷贝：</strong> sendfile/mmap 减用户态内核态往返（Go <code>io.Copy</code> 自动用，见《Go笔记》§6）。</li><li><strong>CPU 飙升排查：</strong> 先分用户态/系统态（top 按线程拆）→ jstack/火焰图定位 → 死循环/GC/自旋/日志刷屏/重试风暴逐一对。</li></ul><h2 id="_6-安全与会话" tabindex="-1">6. 安全与会话 <a class="header-anchor" href="#_6-安全与会话" aria-label="Permalink to &quot;6. 安全与会话&quot;">​</a></h2><p><strong>一句话：Cookie 存客户端必须签名，会话放服务端必须旋转，跨域与注入按清单防。</strong></p><ul><li><strong>Cookie vs Session（常问）：</strong> Cookie 存客户端，Session 是服务端状态；防伪：内容签名/加密、SessionID 纯随机、HttpOnly/Secure/SameSite、登录后旋转、防 CSRF token。</li><li><strong>JWT 本质：</strong> 声明 + 签名，验签后信任（私钥签名、公钥验签，防篡改）。</li><li><strong>清单：</strong> XSS/CSRF/SQL 注入输入校验；CORS 跨域；CDN/WAF/DDoS 防护分层。</li></ul><h2 id="附-与他篇的边界" tabindex="-1">附：与他篇的边界 <a class="header-anchor" href="#附-与他篇的边界" aria-label="Permalink to &quot;附：与他篇的边界&quot;">​</a></h2><ul><li>GMP 调度、锁的语言实现 → 《Go笔记》§2、《Java/Python笔记》§2。</li><li>Reactor/epoll 的框架用法（Nginx/Gin/Netty）→ 《系统设计笔记》§1、《Go笔记》§4。</li><li>延迟表是估算工具，压测与容量规划 → 《系统设计笔记》§5。</li></ul>',11))])}const p=d(B,[["render",C]]);export{c as __pageData,p as default};
